    WATER_REQ = 7
    supply = day_context['supply']
    my_hp = my_status['hp']
    my_budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = {k: v for k, v in opponents_status.items() if v['alive']}
    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.5)

    # Gather yesterday's bids from opponents' previous_trace
    yesterday_bids = []
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev and prev['bid'] is not None:
            yesterday_bids.append(prev['bid'])

    # Base bid: use supply to determine a reasonable water cost
    # If low supply, bids rise; else moderate
    if supply < 16:
        base_cost = DAILY_SALARY
    elif supply < 20:
        base_cost = DAILY_SALARY * 0.7
    else:
        base_cost = DAILY_SALARY * 0.5

    # Adjust based on yesterday's maximum bid (aggression)
    if yesterday_bids:
        max_yesterday = max(yesterday_bids)
        # If opponent was very aggressive, they may continue, so be conservative if healthy
        if max_yesterday > DAILY_SALARY * 1.2:
            if my_hp > 4:
                target = base_cost * 0.7
            else:
                target = min(base_cost * 1.2, DAILY_SALARY * 1.1)
        elif max_yesterday > DAILY_SALARY * 0.9:
            target = max(base_cost, max_yesterday * 0.8)
        else:
            target = max(base_cost, max_yesterday * 1.05)
    else:
        target = base_cost

    # Urgency due to HP
    if my_hp <= 2 or no_water_days > 0:
        target = max(target, DAILY_SALARY * 0.9)
    if my_hp <= 1:
        target = max(target, DAILY_SALARY * 1.05)

    # Ensure not exceeding budget
    bid = min(my_budget, target)

    # Round to avoid float index issues (though not needed here)
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    # If no opponents, take what we can.
    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.6))

    # Read yesterday bids for immediate pressure signal.
    prev_bids = []
    for _, opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate how contested this day likely is.
    # If many opponents were bidding high yesterday, we must bid higher to avoid running out.
    high_bids = [b for b in prev_bids if b >= DAILY_SALARY * 0.8]
    any_very_high = any(b >= DAILY_SALARY * 1.2 for b in prev_bids)  # aggressive ceiling behavior

    # Base bid: moderate fraction to stay competitive without overspending.
    # Adjust with my health and no-water streak.
    if my_hp <= 2 or my_no_water >= 2:
        urgency = 1.0
    elif my_hp <= 4 or my_no_water == 1:
        urgency = 0.7
    else:
        urgency = 0.45

    # Supply-based scaling: when supply is closer to MIN, competition is higher.
    # Normalize supply in [0,1].
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))
    scarcity = 1.0 - supply_norm

    # Pressure factor from opponents' yesterday behavior.
    pressure = 0.0
    if len(prev_bids) > 0:
        pressure = min(1.0, (len(high_bids) / float(len(prev_bids))) * 1.2)
    if any_very_high:
        pressure = min(1.0, pressure + 0.25)

    # Target bid formula.
    # Keep it below my budget and below a reasonable fraction of salary.
    target = DAILY_SALARY * (0.35 + 0.55 * urgency + 0.25 * scarcity + 0.25 * pressure)

    # If yesterday bids were mostly low (conservation), we can slightly underbid.
    if prev_bids:
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if avg_prev <= DAILY_SALARY * 0.65:
            target *= 0.9

    # If yesterday had very high bids, we must meet them partially.
    if prev_bids:
        max_prev = max(prev_bids)
        if max_prev >= DAILY_SALARY * 0.85:
            target = max(target, min(my_budget, max_prev * 0.75))

    # Final cap: cannot exceed budget.
    bid = max(0.0, min(my_budget, target))

    # Ensure we don't bid trivially low when we are at risk.
    if my_hp <= 3:
        bid = max(bid, min(my_budget, DAILY_SALARY * 0.75))

    return float(bid)
